import{_ as r,l as s,o as a,c as l,v as t,p as n,x as o,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"几何精度与鲁棒性","description":"","frontmatter":{"title":"几何精度与鲁棒性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/geometric-robustness.md","filePath":"cs/geometric-robustness.md","lastUpdated":1789023840000}'),h={name:"cs/geometric-robustness.md"};function u(m,e,_,E,A,b){const i=s("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="几何精度与鲁棒性" tabindex="-1">几何精度与鲁棒性 <a class="header-anchor" href="#几何精度与鲁棒性" aria-label="Permalink to &quot;几何精度与鲁棒性&quot;">​</a></h1><div class="epigraph"><p>叉积符号判左右；浮点舍入会把「几乎共线」判错，算法拓扑崩坏。精确谓词或自适应算术才能稳住。</p><footer>—— 据 Shewchuk, Adaptive Precision Floating-Point Arithmetic and Fast Robust Geometric Predicates, 1997；Yap 精确几何计算整理</footer></div><p>上一课<a href="/cs/point-location">点定位</a>假定左右判定正确。本单元几何在此收束：实现层。缺口是<strong>谓词</strong>：<code>orient2d</code>、<code>incircle</code> 的符号。浮点可能错号。不重写凸包栈。下一单元随机与近似。不把光刻套刻当本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>凸包、BO、Delaunay 都依赖谓词。错一次：凸包自交、三角非空圆。对策：整数坐标 + 精确整数叉积；自适应浮点（Shewchuk）：快路径浮点，误差界不够则精确。符号扰动（Simulation of Simplicity）去掉共线/共圆退化。</p><p>缺口是健壮，不是更快渐近。</p><h3 id="不是「多加点-epsilon」" tabindex="-1">不是「多加点 epsilon」 <a class="header-anchor" href="#不是「多加点-epsilon」" aria-label="Permalink to &quot;不是「多加点 epsilon」&quot;">​</a></h3><p>固定 \\(\\varepsilon\\) 比较会引入新不一致（\\(a\\lt b\\)、\\(b\\lt c\\) 但 \\(a\\gt c\\)）。要的是精确符号或一致扰动。</p><p><span class="marginnote">Shewchuk 1997 谓词。CGAL 精确核。后课 Karger 离开几何。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>优先整数输入。谓词封装，禁止散落 <code>double</code> 比较。退化用 SoS 或显式分支。过滤：区间算术快速排除。</p>',11)),(a(),n(p,null,{default:o(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRED%5B%22orient%20%2F%20incircle%22%5D%20--%3E%20FLT%5B%22%E6%B5%AE%E7%82%B9%E8%BF%87%E6%BB%A4%22%5D%0A%20%20FLT%20--%3E%20EXACT%5B%22%E7%B2%BE%E7%A1%AE%20%2F%20%E8%87%AA%E9%80%82%E5%BA%94%22%5D%0A%20%20PRED%20--%3E%20SOS%5B%22%E7%AC%A6%E5%8F%B7%E6%89%B0%E5%8A%A8%E5%8E%BB%E9%80%80%E5%8C%96%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>输出坐标若需画图可再舍入，拓扑已定。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>定向符号 = 行列式符号。误差分析给出何时浮点可信。自适应只对难实例付精确代价。与 NTT：那里模精确；这里实数嵌入。与 LP：病态约束同类数值，但 LP 用主元，几何用谓词。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整任意精度核。不写曲面。几何课序结束。后课默认：几何算法的正确实现依赖精确谓词。下一课 Karger 最小割。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>拓扑正确 = 谓词符号正确。</li><li>自适应精确或整数核；慎用固定 \\(\\varepsilon\\)。</li><li>退化用扰动或显式处理。</li><li>出处：Shewchuk, 1997。</li></ul>',7))])}const P=r(h,[["render",u]]);export{B as __pageData,P as default};
